id": "6d3f6f35-27f4-4b9b-af4a-5e36a60bc49a", "type": "topic", "title": "Union Organizing, Campaigns, and Employer Conduct", "description": "This section prepares HR students to recognize organizing dynamics and keep employer responses lawful, credible, and ethically defensible.", "children": [{"id": "b14bf373-bf6b-455b-a023-ee67f178e26e", "type": "subtopic", "title": "Organizing strategy", "children": [{"id": "e95bc332-b8a6-4903-b92e-6d666591719a", "type": "concept", "title": "authorization cards"}, {"id": "25d42a15-301d-44aa-aa18-44b981dfbf67", "type": "concept", "title": "organizing committees"}, {"id": "962f28d7-da60-41f6-a27b-625a3d05aee5", "type": "concept", "title": "workplace mapping"}, {"id": "8ac8008d-e762-4030-ac9d-7c2116bde63a", "type": "concept", "title": "salting"}, {"id": "96475672-2c8c-4a3b-ba08-63eb73ed0623", "type": "concept", "title": "digital organizing"}], "description": "Students learn how campaigns build support, identify issues, map workplaces, and mobilize employees."}, {"id": "c8109a5f-421c-41c0-b662-bb53f0058177", "type": "subtopic", "title": "Representation procedures", "children": [{"id": "f431bdd0-5309-4d1d-a88e-163ecd94e848", "type": "concept", "title": "petitions"}, {"id": "6600ac40-0047-4e58-b48c-37dd21a51a35", "type": "concept", "title": "showing of interest"}, {"id": "ebf8bfac-71d8-4c54-8ff9-6bb308f3e58e", "type": "concept", "title": "unit determination"}, {"id": "260fa37a-dfbe-4f70-833a-7680c2b2f030", "type": "concept", "title": "secret-ballot elections"}, {"id": "9e40317a-02cf-48e8-aac8-49c74c0d6c98", "type": "concept", "title": "certification"}], "description": "The class examines elections, card-check arrangements, bargaining-unit disputes, and campaign objections."}, {"id": "708ea763-acfe-48db-929f-7ad6cf87220b", "type": "subtopic", "title": "Lawful employer conduct", "children": [{"id": "fbf91317-df98-4464-b923-a491edbe23b1", "type": "concept", "title": "TIPS framework"}, {"id": "4a7abad5-a174-4159-a5d3-dbc6b7db81dc", "type": "concept", "title": "supervisor training"}, {"id": "c10ff3c5-36e3-4455-9d0c-938324759006", "type": "concept", "title": "neutrality agreements"}, {"id": "e1a7aef3-5dc5-45d8-8545-896dc38e122a", "type": "concept", "title": "captive-audience issues"}, {"id": "1a632a1e-adc1-4a08-96f6-3a24123163f7", "type": "concept", "title": "message discipline"}], "description": "Students learn how to communicate without threats, interrogation, promises, surveillance, or retaliation."}]}, {"id": "3186f4c8-d1fc-465d-acbc-a094ec810206", "type": "topic", "title": "Labor Economics, Power, and Strategic Context", "description": "Students learn why bargaining outcomes depend on economic conditions, institutional rules, labor-market power, public support, and organizational strategy.", "children": [{"id": "a89e0c85-2571-4773-9309-5a8255765385", "type": "subtopic", "title": "Labor-market context", "children": [{"id": "26279c8a-7f5b-42ff-96e9-ad7996275924", "type": "concept", "title": "wage premiums"}, {"id": "b39a571b-a88f-4e4f-a09c-8e78f8a13f21", "type": "concept", "title": "monopsony"}, {"id": "b6c822c1-cf80-4041-a71e-39f40d85acd4", "type": "concept", "title": "productivity"}, {"id": "92e1c8f2-640a-4ec6-99a9-5da378e12c49", "type": "concept", "title": "labor share"}, {"id": "1256d934-c995-48eb-b11f-d3fd95bb0f26", "type": "concept", "title": "inequality"}], "description": "This subtopic connects unions to wages, benefits, turnover, inequality, and labor-market structure."}, {"id": "cdca18be-fcdd-4efb-a58c-a83528f12ed4", "type": "subtopic", "title": "Bargaining power", "children": [{"id": "42e1077d-f94e-430b-9d0e-29b4b9f15778", "type": "concept", "title": "strike threat"}, {"id": "d2f9591c-a2d8-4617-b4d2-53bd3f39aac3", "type": "concept", "title": "replacement workers"}, {"id": "f305764a-f787-40f8-a21a-61962ad8c252", "type": "concept", "title": "public opinion"}, {"id": "b81bd59a-7e63-4ecb-9245-5c33c4373296", "type": "concept", "title": "financial reserves"}, {"id": "b901505f-6c1f-4839-92f6-79d6