update public.learning_paths
set
  title = 'Labor Relations / Collective Bargaining',
  goal = 'Labor Relations / Collective Bargaining',
  summary = 'This course prepares undergraduate Human Resources students to understand labor relations as law, strategy, negotiation, conflict resolution, workplace democracy, and organizational governance. Students learn how unions organize, how collective bargaining agreements are negotiated and administered, how grievances and arbitration work, and how HR professionals can navigate labor-management relationships with legal discipline, ethical judgment, and practical skill.',
